const $=id=>document.getElementById(id);let mode='login',enabled=false,busy=false;
async function call(path,data){const response=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let result;try{result=await response.json();}catch{throw Error('Could not reach GoRide. Check your connection and try again.');}if(!response.ok)throw Error(result.error||'Sign-in could not be completed.');return result;}
function setMode(next){if(busy)return;mode=next;const register=mode==='register',recover=mode==='recover';$('login-heading').textContent=register?'Create your account':recover?'Recover your account':'Welcome back';$('login-info').textContent=register?'Use an email and password for your GoRide bookings.':recover?'Enter your email, saved recovery code and a new password.':'Sign in to manage your rides.';$('submit-login').textContent=register?'Create account':recover?'Reset password':'Sign in';$('password-label').textContent=recover?'New password':'Password';$('password').autocomplete=mode==='login'?'current-password':'new-password';$('password').minLength=mode==='login'?1:15;$('password').value='';$('recovery-code').value='';$('password-help').hidden=mode==='login';$('recovery-input').hidden=!recover;$('recovery-code').required=recover;$('register-consent').hidden=!register;$('account-consent').required=register;$('switch-register').hidden=mode!=='login';$('switch-recover').hidden=mode!=='login';$('switch-login').hidden=mode==='login';$('login-error').textContent='';}
$('switch-register').onclick=()=>setMode('register');$('switch-recover').onclick=()=>setMode('recover');$('switch-login').onclick=()=>setMode('login');
$('email-form').onsubmit=async e=>{e.preventDefault();if(!enabled||busy)return;busy=true;$('submit-login').disabled=true;$('login-error').textContent='';try{const result=await call('/api/customer-auth/'+({login:'password-login',register:'register',recover:'recover'}[mode]),{email:$('email-address').value,password:$('password').value,recoveryCode:$('recovery-code').value,consent:$('account-consent').checked});$('password').value='';$('recovery-code').value='';if(result.recoveryCode){$('saved-recovery').value=result.recoveryCode;$('email-form').hidden=true;$('login-switch').hidden=true;$('recovery-result').hidden=false;$('login-heading').textContent=mode==='register'?'Your account is ready':'Password updated';$('login-info').textContent=mode==='register'?'Save this code before continuing.':'Your old recovery code no longer works. Save this replacement.';$('saved-confirm').checked=false;$('continue-account').disabled=true;}else location.replace('/account');}catch(err){$('login-error').textContent=err.message;}finally{busy=false;$('submit-login').disabled=!enabled;}};
$('saved-confirm').onchange=()=>{$('continue-account').disabled=!$('saved-confirm').checked;};
$('continue-account').onclick=()=>{if($('saved-confirm').checked){$('saved-recovery').value='';location.replace('/account');}};
$('copy-recovery').onclick=async()=>{try{await navigator.clipboard.writeText($('saved-recovery').value);$('copy-recovery').textContent='Copied';}catch{$('saved-recovery').focus();$('saved-recovery').select();$('login-error').textContent='Select and copy the recovery code, then store it privately.';}};
(async()=>{try{const config=await call('/api/customer-auth/config');enabled=config.emailEnabled;$('login-service').hidden=enabled;$('login-service').textContent=enabled?'':'Sign-in is temporarily unavailable. Please try again later.';$('private-preview').hidden=!config.privatePreview;$('submit-login').disabled=!enabled;}catch(e){$('login-service').hidden=false;$('login-service').textContent='We couldn’t load sign-in. Please refresh and try again.';}finally{$('submit-login').textContent=mode==='register'?'Create account':mode==='recover'?'Reset password':'Sign in';}})();
